const trigger = $input.first().json || {};
const data = trigger.body || trigger;

let rawBase = data.base_amount || data.baseAmount || data.monto_base;
let rawAmount = data.amount || data.monto || data.final_amount;
const duration = String(data.duration || data.meses || data.plan || '1 Mes').trim();
const payment_method = String(data.payment_method || data.metodo || data.metodo_pago || 'PayPal / Tarjeta').trim();
let conversation_id = data.conversation_id ? parseInt(data.conversation_id) : 0;
const contact_name = String(data.contact_name || data.nombre || 'Cliente').trim();
const contact_phone = String(data.contact_phone || data.telefono || 'No registrado').trim();
const account_id = data.account_id ? parseInt(data.account_id) : 1;

let baseAmount = 8;
let finalAmount = 8.80;

if (rawBase !== undefined && rawBase !== null && !isNaN(parseFloat(rawBase))) {
  baseAmount = parseFloat(parseFloat(rawBase).toFixed(2));
  finalAmount = parseFloat((baseAmount * 1.10).toFixed(2));
} else if (rawAmount !== undefined && rawAmount !== null && !isNaN(parseFloat(rawAmount))) {
  const parsedAmt = parseFloat(rawAmount);
  if (parsedAmt === 8.80 || parsedAmt === 26.40 || parsedAmt === 52.80 || parsedAmt === 92.40) {
    finalAmount = parsedAmt;
    baseAmount = parseFloat((finalAmount / 1.10).toFixed(2));
  } else if (parsedAmt === 8 || parsedAmt === 24 || parsedAmt === 48 || parsedAmt === 84) {
    baseAmount = parsedAmt;
    finalAmount = parseFloat((baseAmount * 1.10).toFixed(2));
  } else {
    baseAmount = parsedAmt;
    finalAmount = parseFloat((baseAmount * 1.10).toFixed(2));
  }
}

if (!conversation_id && data.query) {
  const m = String(data.query).match(/(?:conversation_id|conversacion|conversation|id)\s*[:=]?\s*(\d+)/i);
  if (m) conversation_id = parseInt(m[1]);
}

if (!conversation_id) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/${account_id}/conversations?status=all`,
      headers: {
        'api_access_token': 'nuwRKpG2bBAQBpRFznfvrMpT',
        'Content-Type': 'application/json'
      },
      json: true
    });
    const convs = res.data?.payload || [];
    if (convs.length > 0) {
      conversation_id = convs[0].id;
    }
  } catch (e) {}
}

return [{
  json: {
    wallet: "0x9a9eDccAF06FD44232896f56e0A73D04EF33B4e0",
    callback_url: "https://n8n.ac4.club/webhook/paymentdone",
    base_amount: baseAmount,
    amount: finalAmount,
    duration: duration,
    payment_method: payment_method,
    conversation_id: conversation_id || 0,
    account_id: account_id || 1,
    contact_name: contact_name,
    contact_phone: contact_phone
  }
}];

const prep = $('Preparar Parámetros y Cálculos').first().json || {};
const walletData = $input.first().json || {};
const addressIn = walletData.address_in || '';

const paylink = `https://pay.card2crypto.org/pay.php?address=${addressIn}&amount=${prep.amount}&email=totaltvusa%40gmail.com&currency=USD`;

const privateNote = `💳 **ENLACE DE PAGO CARD2CRYPTO GENERADO (TVTotal24)**\n\n` +
  `👤 **Contacto:** ${prep.contact_name}\n` +
  `📱 **Teléfono:** ${prep.contact_phone}\n` +
  `💬 **Conversación:** #${prep.conversation_id}\n` +
  `⏱️ **Plan:** ${prep.duration}\n` +
  `💵 **Monto Base:** $${prep.base_amount} USD\n` +
  `📊 **Recargo (10%):** +$${(prep.amount - prep.base_amount).toFixed(2)} USD\n` +
  `💰 **Monto a Pagar:** $${prep.amount} USD\n` +
  `📌 **Método Solicitado:** ${prep.payment_method}\n\n` +
  `🔗 **Enlace de Pago:**\n${paylink}`;

const escapeHtml = (str) => String(str || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const telegramText = `💳 <b>Enlace de Pago Card2Crypto Generado (TVTotal24)</b>\n\n` +
  `👤 <b>Contacto:</b> ${escapeHtml(prep.contact_name)}\n` +
  `📱 <b>Teléfono:</b> ${escapeHtml(prep.contact_phone)}\n` +
  `💬 <b>Conversación:</b> #${prep.conversation_id}\n` +
  `⏱️ <b>Plan:</b> ${escapeHtml(prep.duration)}\n` +
  `💵 <b>Monto Base:</b> $${prep.base_amount} USD (+10% recargo)\n` +
  `💰 <b>Monto a Cobrar:</b> $${prep.amount} USD\n` +
  `📌 <b>Método Solicitado:</b> ${escapeHtml(prep.payment_method)}\n\n` +
  `🔗 <b>Enlace:</b>\n${escapeHtml(paylink)}`;

const whatsappText = `💳 *Enlace de Pago Card2Crypto Generado (TVTotal24)*\n\n` +
  `👤 *Contacto:* ${prep.contact_name}\n` +
  `📱 *Teléfono:* ${prep.contact_phone}\n` +
  `💬 *Conversación:* #${prep.conversation_id}\n` +
  `⏱️ *Plan:* ${prep.duration}\n` +
  `💵 *Monto Base:* $${prep.base_amount} USD (+10% recargo)\n` +
  `💰 *Monto a Cobrar:* $${prep.amount} USD\n` +
  `📌 *Método Solicitado:* ${prep.payment_method}\n\n` +
  `🔗 *Enlace:*\n${paylink}`;

return [{
  json: {
    ...prep,
    address_in: addressIn,
    paylink: paylink,
    private_note: privateNote,
    telegram_text: telegramText,
    whatsapp_text: whatsappText
  }
}];

const data = $('Construir Mensajes y Enlace').first().json || {};
return [{
  json: {
    status: "success",
    paylink: data.paylink,
    amount: data.amount,
    base_amount: data.base_amount,
    duration: data.duration,
    payment_method: data.payment_method,
    message: `Enlace de pago Card2Crypto generado exitosamente por $${data.amount} USD (incluye 10% de recargo sobre el plan base de $${data.base_amount} USD). Entrega este enlace al cliente para que realice su pago con ${data.payment_method}.`
  }
}];
